            fn set_size_and_sync(&mut self, new_bounds: TerminalBounds) {
                self.terminal.set_size(new_bounds);
                self.sync();
            }

            fn sync(&mut self) {
                self.unthrottle();
                self.terminal.sync(self.window, self.cx);
            }

            fn unthrottle(&mut self) {
