        let item_b_id = item_b.entity_id();

        pane.update_in(cx, |pane, window, cx| {
            pane.add_item(Box::new(item_a.clone()), true, true, None, window, cx);
            pane.add_item(Box::new(item_b.clone()), true, true, None, window, cx);
        });

